def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 10)
    grid_height = observation.get("grid_height", 10)
    role = observation.get("self_role", "pursuer")
    # For resource_collection
    resources = observation.get("resources") or []
    # For territory_control
    unclaimed_cells = observation.get("unclaimed_cells") or []
    opponent_territory = observation.get("opponent_territory") or []

    # Determine movement vector, possibly random (using fixed pattern for robustness)
    def move_towards(target):
        dx = 0
        dy = 0
        if target:
            if target[0] > sx:
                dx = 1
            elif target[0] < sx:
                dx = -1
            if target[1] > sy:
                dy = 1
            elif target[1] < sy:
                dy = -1
        else:
            # No target, attempt random step
            # Use a fixed pattern to avoid randomness which could be unstable
            if (sx + sy) % 3 == 0:
                dx, dy = 1, 0
            elif (sx + sy) % 3 == 1:
                dx, dy = -1, 0
            elif (sx + sy) % 3 == 2:
                dx, dy = 0, 1
            # clamp to grid
            nx = sx + dx
            ny = sy + dy
            if not (0 <= nx < grid_width):
                dx = -dx
            if not (0 <= ny < grid_height):
                dy = -dy
        return [dx, dy]

    # Priority order based on env
    if env == "pursuit_evasion":
        if role == "pursuer":
            if ox is not None and oy is not None:
                # Chase opponent
                return move_towards((ox, oy))
            else:
                # Random move
                return move_towards(None)
        else:
            # Evader, try to escape to corner farthest from opponent
            corners = [
                [0, 0],
                [0, grid_height - 1],
                [grid_width - 1, 0],
                [grid_width - 1, grid_height - 1]
            ]
            # pick corner farthest from opponent
            def dist_to_opp(c): return abs(c[0] - ox) + abs(c[1] - oy)
            target_corner = max(corners, key=dist_to_opp)
            return move_towards(target_corner)

    elif env == "territory_control":
        if unclaimed_cells:
            target = min(unclaimed_cells, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
            return move_towards(target)
        elif opponent_territory:
            # Attempt to invade opponent territory (not detailed here)
            target = min(opponent_territory, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
            return move_towards(target)
        else:
            # No targets, maintain position
            return [0,0]

    elif env == "resource_collection":
        if resources:
            target = min(resources, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
            return move_towards(target)
        else:
            # No resources, position randomly or stay put
            return [0, 0]
    else:
        # Default behavior: move towards opponent if known
        return move_towards((ox, oy) if ox is not None and oy is not None else None)

